"""Embed the checked CCE software recipes for the native input adapter."""

import argparse
import json
from pathlib import Path


def generate(source: Path, output: Path):
    document = json.loads(source.read_text())
    data = json.dumps(document, separators=(",", ":"), ensure_ascii=True)
    output.parent.mkdir(parents=True, exist_ok=True)
    output.write_text(
        "// Generated by tools/generate_cce_lowering_cpp.py.\n"
        'static const char kCceLoweringJson[] = R"CCERECIPE(' + data + ')CCERECIPE";\n'
    )


if __name__ == "__main__":
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("source", type=Path)
    parser.add_argument("output", type=Path)
    args = parser.parse_args()
    generate(args.source, args.output)
